window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-8901\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆εκελεικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 383 na letra δ · nº geral 8901</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Decéleia; deceliano. 〈∆εκέλεια〉</p></section></article>\n<article id=\"entry-dgp-8902\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆εκελεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 384 na letra δ · nº geral 8902</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitante de Decélia; deceliano. 〈∆εκέλεια〉</p></section></article>\n<article id=\"entry-dgp-8903\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεκέμβριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 385 na letra δ · nº geral 8903</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de dezembro. [lat.]</p></section></article>\n<article id=\"entry-dgp-8904\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεκέτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 386 na letra δ · nº geral 8904</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 que dura há dez anos 2 de dez anos de idade. 〈δέκα, ἔτος〉</p></section></article>\n<article id=\"entry-dgp-8905\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεκήρης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 387 na letra δ · nº geral 8905</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem dez fileiras de remeiros. 〈δέκα〉</p></section></article>\n<article id=\"entry-dgp-8906\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέκομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 388 na letra δ · nº geral 8906</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = δέχομαι.</p></section></article>\n<article id=\"entry-dgp-8907\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεκτέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 389 na letra δ · nº geral 8907</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de δέχομαι.</p></section></article>\n<article id=\"entry-dgp-8908\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέκτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 390 na letra δ · nº geral 8908</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que recebe; mendigo. 〈δέχομαι〉</p></section></article>\n<article id=\"entry-dgp-8909\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέκτο</h1><div class=\"entry-meta\"><span>DGP · ordem 391 na letra δ · nº geral 8909</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. m.-q.-perf. poét. de δέχομαι.</p></section></article>\n<article id=\"entry-dgp-8910\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεκτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 392 na letra δ · nº geral 8910</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. 1 aceito; admitido 2 agradável a alguém, dat. 〈δέχομαι〉</p></section></article>\n<article id=\"entry-dgp-8911\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέκτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 393 na letra δ · nº geral 8911</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que acolhe, gen. 〈δέχομαι〉</p></section></article>\n<article id=\"entry-dgp-8912\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δελεάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 394 na letra δ · nº geral 8912</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐδελέασα) 1 colocar como isca 2 colocar isca em, ac. 3 apanhar com isca 4 enganar; seduzir ♦ pas. 5 deixar-se apanhar; deixar-se seduzir por, dat. 〈δέλεαρ〉</p></section></article>\n<article id=\"entry-dgp-8913\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέλεαρ, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 395 na letra δ · nº geral 8913</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 isca 2 engodo.</p></section></article>\n<article id=\"entry-dgp-8914\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέλτα (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 396 na letra δ · nº geral 8914</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. 1 delta, 4ª letra do alfabeto 2 embocadura (de rio) em forma de delta 3 púbis feminino.</p></section></article>\n<article id=\"entry-dgp-8915\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δελτίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 397 na letra δ · nº geral 8915</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tabuleta. 〈δέλτος〉</p></section></article>\n<article id=\"entry-dgp-8916\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δελτογράφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 398 na letra δ · nº geral 8916</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que toma nota em tabuletas; que grava na memória. 〈δέλτος, γράφω〉</p></section></article>\n<article id=\"entry-dgp-8917\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δελτόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 399 na letra δ · nº geral 8917</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres. fem. ac. pl. δελτουμένας) tomar nota em tabuletas.</p></section></article>\n<article id=\"entry-dgp-8918\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέλτος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 400 na letra δ · nº geral 8918</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tabuleta de anotação 2 o que está anotado em uma tabuleta; mensagem; testamento; poema 3 tábua da lei.</p></section></article>\n<article id=\"entry-dgp-8919\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δελφάκιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 401 na letra δ · nº geral 8919</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">leitão. 〈δέλφαξ〉</p></section></article>\n<article id=\"entry-dgp-8920\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέλφαξ, ακος (ἡ, ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 402 na letra δ · nº geral 8920</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">porco; leitão.</p></section></article>\n<article id=\"entry-dgp-8921\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ελφικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 403 na letra δ · nº geral 8921</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Delfos; délfico. 〈∆ελφοί〉</p></section></article>\n<article id=\"entry-dgp-8922\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δελφινίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 404 na letra δ · nº geral 8922</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. aor. δελφινίσαντες) mergulhar como um golfinho. 〈δελφίς〉</p></section></article>\n<article id=\"entry-dgp-8923\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ελφίνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 405 na letra δ · nº geral 8923</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 templo de Apolo Delfínio, partic. em Atenas 2 Delfínio, cidade da ilha de Quios.</p></section></article>\n<article id=\"entry-dgp-8924\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δελφινὶς τράπεζα (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 406 na letra δ · nº geral 8924</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mesa com pés em forma de golfinho.</p></section></article>\n<article id=\"entry-dgp-8925\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δελφινοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 407 na letra δ · nº geral 8925</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem golfinhos (mar) 2 que tem golfinho de chumbo ou de ferro (navio). 〈δελφίς, φέρω〉</p></section></article>\n<article id=\"entry-dgp-8926\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δελφίς, ῖνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 408 na letra δ · nº geral 8926</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 delfim; golfinho 2 golfinho, peça de chumbo ou de ferro em forma de golfinho que navios de guerra lançavam contra o navio inimigo para afundá-lo 3 Astron. Delfim, constelação.</p></section></article>\n<article id=\"entry-dgp-8927\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ελφίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 409 na letra δ · nº geral 8927</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de Delfos. 〈∆ελφοί〉</p></section></article>\n<article id=\"entry-dgp-8928\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ελφοί, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 410 na letra δ · nº geral 8928</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Delfos, cidade da Fócida célebre por um templo e um oráculo de Apolo 2 os delfianos 3 o oráculo desse local.</p></section></article>\n<article id=\"entry-dgp-8929\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ελφός, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 411 na letra δ · nº geral 8929</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 de Delfos; delfiano ♦ ὁ ∆ελφός 2 Delfos, filho de Posidão.</p></section></article>\n<article id=\"entry-dgp-8930\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέμας (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 412 na letra δ · nº geral 8930</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só nom. e ac. sing.) 1 corpo; talhe; apa­rência: δέμας ἐϊκυῖα θέῃσιν hom. semelhante às deusas quanto ao aspecto, μητρῷον δ. ésql. o corpo materno, i.e., a mãe, Ἡράκλειον δ. eur. o corpo de Héracles, i.e., Héracles, τοῦ φίλων οἰκετῶν δέμας sóf. um escravo amigo ♦ prep. 2 à maneira de, gen.: δ. πυρὸς αἰθομένοιο hom. à maneira de um fogo ardente. 〈δέμω, δόμος〉</p></section></article>\n<article id=\"entry-dgp-8931\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέμνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 413 na letra δ · nº geral 8931</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estrado 2 colchão 3 cama. 〈δέμω〉</p></section></article>\n<article id=\"entry-dgp-8932\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεμνιοτήρης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 414 na letra δ · nº geral 8932</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que retém alguém na cama 2 que vela sobre, gen. 〈δέμνιον, τηρέω〉</p></section></article>\n<article id=\"entry-dgp-8933\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέμω</h1><div class=\"entry-meta\"><span>DGP · ordem 415 na letra δ · nº geral 8933</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. poét. δέμον, fut. desus., aor. ἔδειμα, perf. desus.; pas. perf. δέδμημαι, m.-q.-perf. ἐδεδμήμην) 1 construir; edificar ♦ méd. 2 construir; fazer erguer para si.</p></section></article>\n<article id=\"entry-dgp-8934\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δενδίλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 416 na letra δ · nº geral 8934</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres. δενδίλλων) fazer sinal com os olhos para alguém, εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-8935\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δένδρεον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 417 na letra δ · nº geral 8935</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = δένδρον.</p></section></article>\n<article id=\"entry-dgp-8936\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δένδρεσι</h1><div class=\"entry-meta\"><span>DGP · ordem 418 na letra δ · nº geral 8936</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. de δένδρος.</p></section></article>\n<article id=\"entry-dgp-8937\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δενδρήεις, ήεσσα, ῆεν</h1><div class=\"entry-meta\"><span>DGP · ordem 419 na letra δ · nº geral 8937</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cheio de árvores 2 de árvore; que diz respeito às árvores 3 que parece uma árvore. 〈δένδρον〉</p></section></article>\n<article id=\"entry-dgp-8938\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δενδρίτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 420 na letra δ · nº geral 8938</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 de árvore; das árvores; arbóreo 2 protetor das árvores, epít. de Dioniso 3 οἱ ∆ενδρῖται luc. os Dendrites, povo fictício. 〈δένδρον〉</p></section></article>\n<article id=\"entry-dgp-8939\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δενδροκομικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 421 na letra δ · nº geral 8939</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que diz respeito à floresta 2 que concerne à preservação das árvores. 〈δένδρον, κόμη e κομέω〉</p></section></article>\n<article id=\"entry-dgp-8940\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δενδρόκομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 422 na letra δ · nº geral 8940</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">coberto de arvoredo frondoso. 〈δένδρον, κόμη〉</p></section></article>\n<article id=\"entry-dgp-8941\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δενδροκόμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 423 na letra δ · nº geral 8941</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que cuida das árvores. 〈δένδρον, κομέω〉</p></section></article>\n<article id=\"entry-dgp-8942\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δενδροκοπέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 424 na letra δ · nº geral 8942</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cortar árvores. 〈δένδρον, κόπτω〉</p></section></article>\n<article id=\"entry-dgp-8943\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δένδρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 425 na letra δ · nº geral 8943</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 árvore 2 madeira.</p></section></article>\n<article id=\"entry-dgp-8944\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δενδροπήμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 426 na letra δ · nº geral 8944</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος nocivo para as árvores. 〈δένδρον, πῆμα〉</p></section></article>\n<article id=\"entry-dgp-8945\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δένδρος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 427 na letra δ · nº geral 8945</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">δένδρον.</p></section></article>\n<article id=\"entry-dgp-8946\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δενδροτομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 428 na letra δ · nº geral 8946</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cortar as árvores de um país, ac.; devastar. 〈δένδρον, τέμνω〉</p></section></article>\n<article id=\"entry-dgp-8947\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δενδροφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 429 na letra δ · nº geral 8947</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que produz árvores. 〈δένδρον, φέρω〉</p></section></article>\n<article id=\"entry-dgp-8948\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δενδρόφυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 430 na letra δ · nº geral 8948</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 arborizado 2 com sinais de árvore (rocha). 〈δένδρον, φύω〉</p></section></article>\n<article id=\"entry-dgp-8949\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεννάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 431 na letra δ · nº geral 8949</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. δεννάσω; aor. ἐδέννασα, perf. desus.) 1 maltratar; ultrajar; injuriar alguém, ac. 2 proferir como insulto, ac.: κακὰ ῥήματα δεννάζων sóf. insultando com palavras horríveis. 〈δέννος〉</p></section></article>\n<article id=\"entry-dgp-8950\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέννος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 432 na letra δ · nº geral 8950</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">censura ultrajante; insulto.</p></section></article>\n<article id=\"entry-dgp-8951\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέξαι</h1><div class=\"entry-meta\"><span>DGP · ordem 433 na letra δ · nº geral 8951</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 imper. aor. de δέχομαι 2 jôn. = δεῖξαι, inf. aor. de δείκνυμι.</p></section></article>\n<article id=\"entry-dgp-8952\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξαίατο</h1><div class=\"entry-meta\"><span>DGP · ordem 434 na letra δ · nº geral 8952</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. poét. opt. aor. de δέχομαι.</p></section></article>\n<article id=\"entry-dgp-8953\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξαμενή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 435 na letra δ · nº geral 8953</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 reservatório de água; cisterna; piscina 2 Filos. matéria passível de tomar formas. 〈δέχομαι〉</p></section></article>\n<article id=\"entry-dgp-8954\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιά, ᾶς</h1><div class=\"entry-meta\"><span>DGP · ordem 436 na letra δ · nº geral 8954</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. δεξιή (ἡ) cf. δεξιός.</p></section></article>\n<article id=\"entry-dgp-8955\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιή</h1><div class=\"entry-meta\"><span>DGP · ordem 437 na letra δ · nº geral 8955</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = δεξιά.</p></section></article>\n<article id=\"entry-dgp-8956\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξίμηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 438 na letra δ · nº geral 8956</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">onde se recebem carneiros que serão imolados; rico de vítimas para o sacrifício. 〈δέχομαι, μῆλον〉</p></section></article>\n<article id=\"entry-dgp-8957\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιοβόλος</h1><div class=\"entry-meta\"><span>DGP · ordem 439 na letra δ · nº geral 8957</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e δεξιολάβος, ου (ὁ) bíbl. guarda-costas; lanceiro. 〈δεξιός, λαμβάνω〉</p></section></article>\n<article id=\"entry-dgp-8958\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 440 na letra δ · nº geral 8958</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐδεξιούμην, fut. δεξιώσομαι, aor. ἐδεξιωσάμην, perf. desus.; aor. pas. ἐδεξιώθην) 1 estender ou erguer a mão direita para saudar ou rezar: θεοῖσι πρῶτα δεξιώσομαι ésql. estenderei primeiro a mão para os deuses 2 dar as boas vindas; acolher cordialmente; saudar alguém, ac.: τίς ἡμᾶς ἰδὼν τοιοῖσδ᾽ ἐπαίνοις οὐχὶ δεξιώσεται sóf. quem, ao nos ver, não nos saudará com tais elogios? ♦ pas. 3 ser saudado com a mão direita. 〈δεξιά〉</p></section></article>\n<article id=\"entry-dgp-8959\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 441 na letra δ · nº geral 8959</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que está à direita; direito; direita: δεξιὸς ὦμος hom. ombro direito; ἐπὶ δεξιόφιν hom., ἐπὶ ou εἰς δεξιά para a direita 2 de bom augúrio; favorável 3 destro; industrioso; hábil: δεξιὸς περὶ τὰς δίκας plat. hábil nos processos 4 cortês; solícito; disposto ♦ ἡ δεξιά 5 a mão direita: δεξιῇ ἠσπάζοντο hom. saudavam com a mão direita, δ. ἀνατείνειν, ἐμβάλλειν ou διδόναι τινί estender a mão a alguém, ἐκ δεξιᾶς, ἐν ou ἐπὶ δεξιᾷ, εἰς δεξιάν à direita 6 compromisso: δεξιὰν λαβεῖν καὶ δοῦναι xen. tomar e dar a mão direita, i.e., assumir compromisso, trocar juramento, ἀνακαλεῖ δεξιάς eur. evocava os compromissos da mão direita♦ τὸ δεξιόν 7 fileira direita de um exército ♦ τὰ δεξιά 8 o lado direito.</p></section></article>\n<article id=\"entry-dgp-8960\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιόσειρος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 442 na letra δ · nº geral 8960</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 preso à direita do varal do carro e, portanto, mais livre; impetuoso (animal) 2 vigoroso; propício (deus). 〈δεξιός, σειρά〉</p></section></article>\n<article id=\"entry-dgp-8961\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 443 na letra δ · nº geral 8961</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 destreza; habilidade; desenvoltura 2 amabilidade; afabilidade 3 favorecimento; oportu­nidade 4 retidão. 〈δεξιός〉</p></section></article>\n<article id=\"entry-dgp-8962\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιοφανής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 444 na letra δ · nº geral 8962</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que aparece à direita. 〈δεξιός, φαίνομαι〉</p></section></article>\n<article id=\"entry-dgp-8963\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιόφιν</h1><div class=\"entry-meta\"><span>DGP · ordem 445 na letra δ · nº geral 8963</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. instr. ou locat. de δεξιός.</p></section></article>\n<article id=\"entry-dgp-8964\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 446 na letra δ · nº geral 8964</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de receber, de acolher. 〈δέχομαι〉</p></section></article>\n<article id=\"entry-dgp-8965\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιτερῆφι</h1><div class=\"entry-meta\"><span>DGP · ordem 447 na letra δ · nº geral 8965</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép., locat. de δεξιτερός.</p></section></article>\n<article id=\"entry-dgp-8966\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιτερός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 448 na letra δ · nº geral 8966</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que fica à direita (membros do corpo) ♦ ἡ δεξιτερή jôn. 2 a mão direita ♦ δεξιτερῆφι ép. 3 locat. do lado direito; à direita 4 instr. com a mão direta. 〈δεξιός〉</p></section></article>\n<article id=\"entry-dgp-8967\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξίωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 449 na letra δ · nº geral 8967</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sinal de amizade; boa acolhida 2 objeto de afeição. 〈δεξιόομαι〉</p></section></article>\n<article id=\"entry-dgp-8968\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιώνυμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 450 na letra δ · nº geral 8968</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem direito por nome: χερσὶ δεξιωνύμοις ésql. com as mãos denominadas direitas, com as mãos direitas. 〈δεξιός, ὄνομα〉</p></section></article>\n<article id=\"entry-dgp-8969\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξιῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 451 na letra δ · nº geral 8969</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 habilmente; destramente; de modo apro­priado 2 de bom augúrio. 〈δεξιός〉</p></section></article>\n<article id=\"entry-dgp-8970\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξίωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 452 na letra δ · nº geral 8970</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 saudação; acolhida 2 receptividade; afabilidade 3 hospitalidade 4 solicitação (de voto); manobra política; conchavo. 〈δεξιόομαι〉</p></section></article>\n<article id=\"entry-dgp-8971\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέξο</h1><div class=\"entry-meta\"><span>DGP · ordem 453 na letra δ · nº geral 8971</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">imper. perf. ép. ou aor. sinc. poét. de δέχομαι.</p></section></article>\n<article id=\"entry-dgp-8972\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεξοίατο</h1><div class=\"entry-meta\"><span>DGP · ordem 454 na letra δ · nº geral 8972</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. opt. fut. poét. de δέχομαι.</p></section></article>\n<article id=\"entry-dgp-8973\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέξομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 455 na letra δ · nº geral 8973</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. δέχομαι.</p></section></article>\n<article id=\"entry-dgp-8974\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέξω</h1><div class=\"entry-meta\"><span>DGP · ordem 456 na letra δ · nº geral 8974</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = δείξω, fut. ind. ou subj. aor. de δείκνυμι.</p></section></article>\n<article id=\"entry-dgp-8975\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεοίατο</h1><div class=\"entry-meta\"><span>DGP · ordem 457 na letra δ · nº geral 8975</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. opt. pres. méd. jôn. de δέω2.</p></section></article>\n<article id=\"entry-dgp-8976\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 458 na letra δ · nº geral 8976</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. δέω1 e 2.</p></section></article>\n<article id=\"entry-dgp-8977\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέον1</h1><div class=\"entry-meta\"><span>DGP · ordem 459 na letra δ · nº geral 8977</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. impf. poét. de δέω1.</p></section></article>\n<article id=\"entry-dgp-8978\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέον2</h1><div class=\"entry-meta\"><span>DGP · ordem 460 na letra δ · nº geral 8978</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. n. de δέω2.</p></section></article>\n<article id=\"entry-dgp-8979\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέον3, οντος</h1><div class=\"entry-meta\"><span>DGP · ordem 461 na letra δ · nº geral 8979</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 com art., o que é necessário; o que é preciso; o dever: τὰ δέοντα εἰπεῖν, πράττειν dizer ou fazer o que é preciso, θᾶττον τοῦ δέοντος, μᾶλλον ou πλεῖον τοῦ δ. mais rápido que o necessário; mais que o necessário, ἐν τῷ δέοντι her. oportunamente; a propósito, εἰς τὸ δέον χρῆσθαι her. usar por necessidade, ἐς τὸ δέον παραγίνεσθαι her. acontecer quando necessário ou a propósito; vir a calhar, πρὸ τοῦ δέοντος sóf. antes do momento oportuno 2 sem art., coisa útil; coisa necessária, adequada, conveniente: ἐν δέοντι no momento certo, ἐς δέον πάρεστι sóf. apresenta-se adequado, ἐς δέον λέγειν dem. falar quando convém, ἐς οὐδὲν δέον ἀναλίσκειν dem. despender sem nenhuma utilidade.</p></section></article>\n<article id=\"entry-dgp-8980\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέοντο</h1><div class=\"entry-meta\"><span>DGP · ordem 462 na letra δ · nº geral 8980</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. impf. méd. poét. de δέω1.</p></section></article>\n<article id=\"entry-dgp-8981\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέος, δέους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 463 na letra δ · nº geral 8981</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 medo; temor: εἰς μέγα δέος κα­τέστησαν tuc. passaram a ter um intenso medo, τεθνᾶσι τῷ δέει τοὺς τοιούτους ἀποστόλους dem. morrem de medo diante de enviados desse tipo, δέος ἴσχετε μηδὲν ὧν αὐδῶ sóf. não tenhais medo algum do que estou dizendo 2 temor respeitoso; respeito; reverência: ἵνα γὰρ δέος, ἔνθα καὶ αἰδώς plat. onde há o temor; há também o respeito 3 meio de inspirar temor; ameaça: ἢ τοίνυν δεινότερόν τι τούτου δέος εὑρετέον ἐστίν tuc. ou bem há que encontrar uma ameaça mais terrível que esta (a morte).</p></section></article>\n<article id=\"entry-dgp-8982\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέπας (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 464 na letra δ · nº geral 8982</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(dat. δέπαϊ, δέπαι ou δέπᾳ; pl. nom. ac. δέπα, gen. δεπάων, dat. δεπάεσσσι ou δέπασσι) taça; copo.</p></section></article>\n<article id=\"entry-dgp-8983\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεράς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 465 na letra δ · nº geral 8983</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">δειράς.</p></section></article>\n<article id=\"entry-dgp-8984\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέρας, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 466 na letra δ · nº geral 8984</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pele; couro: δ. πάγχρυσον tosão de ouro.</p></section></article>\n<article id=\"entry-dgp-8985\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δερβαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 467 na letra δ · nº geral 8985</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. de Derbe, cidade da Licaônia.</p></section></article>\n<article id=\"entry-dgp-8986\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέργμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 468 na letra δ · nº geral 8986</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">olhar penetrante. 〈δέρκομαι〉</p></section></article>\n<article id=\"entry-dgp-8987\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέρη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 469 na letra δ · nº geral 8987</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pescoço 2 garganta; goela.</p></section></article>\n<article id=\"entry-dgp-8988\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δερκέσκετο</h1><div class=\"entry-meta\"><span>DGP · ordem 470 na letra δ · nº geral 8988</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. iter. de δέρκομαι.</p></section></article>\n<article id=\"entry-dgp-8989\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέρκομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 471 na letra δ · nº geral 8989</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐδερκόμην, fut. rec. δέρξομαι, aor. ἐδέρχθην, aor.2 ἔδρακον, perf. com sent. de pres. δέδορκα) 1 olhar fixamente; lançar um olhar fixo ou penetrante sobre algo, ac., εἰς ou κατά ou πρός e ac.: δερκόμενοι Τρῶας hom. os olhos fixos nos troianos, πόντον ἐπ᾽ ἀτρύγετον δερκέσκετο hom. detinha o olhar sobre o mar infecundo, δεδορκὼς τοὺς ἐμοὺς κατὰ στίβους hom. detendo o olhar sobre minhas pegadas 2 ver; notar; perceber: δ. κτύπον ésql. perceber um ruído 3 ter a faculdade da visão: ὁ δεδορκώς aquele que vê, em op. ao cego ou ao morto 4 lançar um olhar de determinado modo, adv. ou predic. ou ac.: δεινὸν δερκόμενοι hom. lançando um olhar terrível, αἰετὸς ὀξύτατος δέρκεσθαι hom. a águia é que lança o mais agudo olhar, πῦρ ὀφθαλμοῖσι δεδορκώς hom. tendo nos olhos um olhar de fogo 5 brilhar; iluminar: δέδορκεν φέγγος pínd. brilha a luz da glória.</p></section></article>\n<article id=\"entry-dgp-8990\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέρμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 472 na letra δ · nº geral 8990</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pele 2 couro 3 carapaça de tartaruga 4 casca de árvore 5 pele de um fruto. 〈δέρω〉</p></section></article>\n<article id=\"entry-dgp-8991\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δερμάτινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 473 na letra δ · nº geral 8991</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de pele; de couro. 〈δέρμα〉</p></section></article>\n<article id=\"entry-dgp-8992\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέρξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 474 na letra δ · nº geral 8992</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sentido da visão. 〈δέρκομαι〉</p></section></article>\n<article id=\"entry-dgp-8993\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέρον</h1><div class=\"entry-meta\"><span>DGP · ordem 475 na letra δ · nº geral 8993</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. poét. de δέρω.</p></section></article>\n<article id=\"entry-dgp-8994\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέρος, ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 476 na letra δ · nº geral 8994</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pele.</p></section></article>\n<article id=\"entry-dgp-8995\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέρρις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 477 na letra δ · nº geral 8995</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pele; couro 2 manta de couro; coberta de couro 3 cobertura de couro.</p></section></article>\n<article id=\"entry-dgp-8996\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέρτρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 478 na letra δ · nº geral 8996</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 membrana dos intestinos 2 entra­nhas; vísceras. 〈δέρω〉</p></section></article>\n<article id=\"entry-dgp-8997\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέρω</h1><div class=\"entry-meta\"><span>DGP · ordem 479 na letra δ · nº geral 8997</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔδερον, fut. δερῶ, aor. ἔδειρα, perf. desus.; pas. fut. rec. δαρήσομαι, aor. ἐδάρθην, aor.2 ἐδάρην, perf. δέδαρμαι) 1 esfolar: ἀσκὸν δείρειν, δ. τινὰ θύλακον ar. esfolar alguém para fazer um odre, um saco 2 esfolar com pancadas; surrar; castigar.</p></section></article>\n<article id=\"entry-dgp-8998\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεσμά, ῶν (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 480 na letra δ · nº geral 8998</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">δεσμός.</p></section></article>\n<article id=\"entry-dgp-8999\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δέσμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 481 na letra δ · nº geral 8999</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 liame; laço; elo 2 fita de cabelo. 〈δέω1〉</p></section></article>\n<article id=\"entry-dgp-9000\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δεσμεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 482 na letra δ · nº geral 9000</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e aor.) 1 ligar; atar; encadear uma coisa, ac., a outra, ἐκ e gen. 2 reunir em feixe. 〈δεσμός〉</p></section></article>";
